"""Small exact UTC lookup tables generated by the checked shared transform."""
import threading
import torch
import numpy as np
from ..v5.transforms_v1 import DAY_US
from ..v5.phase2_ar_shards.contract import FRAMES

_LOCK=threading.Lock()


class ClockTables:
    DAYS=24000  # Out-of-domain/subsecond clocks use the ordinary checked path.

    def __init__(self,transform,device):
        self.device=torch.device(device)

        def fields(clocks,frame):
            clocks=clocks.reshape(-1,64);shape=(*clocks.shape,18)
            made=transform(torch.zeros(shape,device=device),
                           torch.zeros(shape,device=device,dtype=torch.bool),clocks,frame)
            return made.values[...,18:].reshape(-1,9)

        seconds=20000*DAY_US+torch.arange(86400,device=device,dtype=torch.int64)*1_000_000
        self.clock=fields(seconds,FRAMES[0])[:,2:4].clone()
        days=torch.arange(self.DAYS,device=device,dtype=torch.int64)*DAY_US+1_000_000
        self.days=fields(days,FRAMES[0])[:,5:9].clone()
        ends=(torch.arange(64,device=device,dtype=torch.int64)+1)*1_000_000
        shape=(5,64,18)
        made=transform(torch.zeros(shape,device=device),
                       torch.zeros(shape,device=device,dtype=torch.bool),ends.expand(5,-1),
                       torch.tensor(FRAMES,device=device,dtype=torch.int64))
        self.frames=made.values[:,0,19].clone()
        if sum(v.numel()*v.element_size() for v in (self.clock,self.days,self.frames))>2*1024**2:
            raise MemoryError('UTC tables exceed their explicit shared budget')
        # Tables are read-only across preparation streams. Publish only once all
        # construction on this worker's CUDA stream has completed.
        torch.cuda.current_stream(device).synchronize()

    def pool(self,clocks,frame,*,_cpu_clocks=None):
        if _cpu_clocks is None:
            valid=(clocks>0).all() & (torch.diff(clocks)>0).all()
            covered=((clocks%1_000_000)==0).all() & ((clocks//DAY_US)<self.DAYS).all()
            valid,covered=torch.stack((valid,covered)).cpu().tolist()
        else:
            # These are the immutable receipt-checked clocks from which this
            # session's GPU clock tensor was copied, not a caller approximation.
            if _cpu_clocks.dtype!=np.int64 or _cpu_clocks.shape!=tuple(clocks.shape):
                raise ValueError('CPU/GPU source clock geometry differs')
            valid,covered=clock_domain(_cpu_clocks,self.DAYS)
        if not valid:raise ValueError('Cached clocks must be positive and strictly ordered')
        if not covered:return None
        values=torch.empty((len(clocks),9),device=self.device,dtype=torch.float32)
        values[:,0]=0  # Restored to each window's relative positions on gather.
        values[:,1]=self.frames[frame]
        values[:,2:4]=self.clock[(clocks//1_000_000)%86400]
        values[0,4]=0
        values[1:,4]=torch.log1p(torch.diff(clocks).double()/FRAMES[frame])
        values[:,5:9]=self.days[clocks//DAY_US]
        return values,torch.ones_like(values,dtype=torch.bool)


def clock_domain(clocks,days=ClockTables.DAYS):
    return (bool((clocks>0).all() and (np.diff(clocks)>0).all()),
            bool(((clocks%1_000_000)==0).all() and ((clocks//DAY_US)<days).all()))


def cached_clock_pool(teacher,transform,clocks,frame,*,_cpu_clocks=None):
    if clocks.device.type!='cuda':return None
    with _LOCK:
        tables=getattr(teacher,'_phase2_clock_tables',None)
        if tables is None:
            tables={};teacher._phase2_clock_tables=tables
        key=str(clocks.device)
        if key not in tables:tables[key]=ClockTables(transform,clocks.device)
        table=tables[key]
    return table.pool(clocks,frame,_cpu_clocks=_cpu_clocks)
